from pathlib import Path
import json
rows=[
('11','Tres combinaciones, un punto de partida','No siempre hace falta cambiar todo el look.','No siempre hace falta cambiar todo el look. Si no sabés por dónde empezar, mirá estas tres combinaciones de nuestro perfil: beige con negro, vino con violeta y marrón con marrón. La idea es elegir primero una prenda de base y después pensar qué tono querés sumar. Son referencias de publicaciones anteriores. Comentá cuál de estas combinaciones te gustaría ver de cerca.',['conjunto-beige.jpg','conjunto-uva.jpg','conjunto-marron.jpg'],['DZirs6Clrw8','DZisj6QFh5H','DZirEg3FlK3'],[('No siempre hace falta','cold_open','Palabras cinéticas debajo del rostro.'),('estas tres combinaciones','tarjetas','Cámara arriba; tres fotos reales sobre hoja marfil.'),('beige con negro','lista_1','Resaltar beige + negro.'),('vino con violeta','lista_2','Resaltar vino + violeta.'),('marrón con marrón','lista_3','Resaltar marrón + marrón.'),('una prenda de base','diagrama','BASE → TONO DE APOYO, trazo SVG con longitud real.'),('publicaciones anteriores','nota','Referencias de inspiración, no inventario vigente.'),('Comentá cuál','cierre','Logo + un CTA: cuál combinación querés ver de cerca.')]),
('12','El detalle cambia la lectura','Antes de quedarte sólo con el color, mirá el detalle.','Antes de quedarte sólo con el color, mirá el detalle. En esta referencia, la blusa es sin mangas y tiene fruncido. En estas otras, el cuello alto es el protagonista. Cuando mirás una prenda por foto, fijate en el cuello, las mangas y los detalles visibles. Eso te da más información para imaginar tu combinación. Comentá qué detalle querés que mostremos de cerca.',['blusa.jpg','verde.jpg','chocolate.jpg'],['DYc8VybRql_','DZ74Wm0RHDo','DYc74FaR_lG'],[('mirá el detalle','cold_open','Gancho breve, acercamiento moderado a la cámara.'),('sin mangas','producto','Blusa real y rótulo SIN MANGAS.'),('tiene fruncido','llamada','Acercamiento real y llamada SVG en la foto, fuera del rostro.'),('el cuello alto','diptico','Cuellos verde y chocolate en papel; cámara circular separada.'),('el cuello, las mangas','lista','CUELLO / MANGAS / DETALLES, uno por término hablado.'),('más información','comparacion','FOTO GENERAL → MIRADA DE CERCA, sin cifras inventadas.'),('Comentá qué','cierre','Logo + un CTA: qué detalle querés ver de cerca.')]),
('13','Una capa abre otra idea','¿Querés pensar otra combinación? Empezá por una capa.','¿Querés pensar otra combinación? Empezá por una capa. En nuestro perfil tenemos esta referencia de chalecos para combinar sobre una camisa. Y también este look con azul y crema, donde una capa tiene otro lugar en la composición. Son dos ideas distintas, no una regla para vestirte. Mirá la base, después la capa y al final cómo conversan los tonos. Comentá qué combinación querés que armemos en el próximo video.',['chaleco-a.jpg','azul-crema.jpg'],['DaszDt2xnFK','DaeBh6olslD'],[('Empezá por una capa','cold_open','Gancho en dos líneas y transición cúbica de 0,7 s.'),('referencia de chalecos','diagrama','Foto real + CAMISA + CHALECO como idea sugerida.'),('azul y crema','producto','Look real en tarjeta editorial, lejos de la cámara.'),('dos ideas distintas','comparacion','Comparar dos referencias sin crear un look falso.'),('la base','paso_1','BASE se revela al decirse.'),('la capa','paso_2','CAPA se conecta por trazo SVG.'),('los tonos','paso_3','TONOS y muestras aproximadas; ropa sin recolor.'),('Comentá qué combinación','cierre','Logo + un CTA: qué combinación querés en el próximo video.')])]
root=Path('.')
brief=dict(estado='Pendiente de grabación real. Guiones propuestos, no transcripciones.',formato=dict(width=1080,height=1920,fps=30,duracion_objetivo_s=[25,35]),idioma='Conservar el de la grabación enviada; no traducir',camara='Cara visible; comprobar y ocultar ubicaciones o datos privados antes del render',paleta=dict(olivo='#4F5533',oscuro='#30371F',papel='#F4F0E6',acento='#C4AB79',tinta='#20251B'),tipografia=['Inter','Cormorant Garamond'],videos=[])
md='# Índigo · tres videos hablados\n\nFormato elegido: vertical 9:16, 25–35 segundos, con grabación real. Estos guiones son propuestas para grabar; se ajustarán al contenido y al idioma de la toma enviada. Todavía no son transcripciones ni cortes del material.\n\n'
for id,title,hook,script,assets,postids,beats in rows:
 urls=['https://www.instagram.com/indigopy_/'+('reel/' if p=='DaszDt2xnFK' else 'p/')+p+'/' for p in postids]
 brief['videos'].append(dict(id=id,titulo=title,gancho=hook,guion_sugerido=script,recursos=assets,fuentes=urls,beats=[dict(cue_frase=q,tipo=t,visual=v,word_start_index=None,word_end_index=None,cut_start_s=None,cut_end_s=None) for q,t,v in beats]))
 md+=f'## {id} · {title}\n\n**Gancho:** {hook}\n\n{script}\n\n'
md+='## Cómo grabar\n\nUna toma larga con los tres temas o tres tomas separadas. Dejá una pausa entre ideas y unos segundos libres al principio y al final. Usá un fondo neutro sin dirección, vistas de ubicación, documentos ni datos privados. Luz frontal, voz clara, cara visible y un poco de espacio alrededor para reencuadrar. La edición conservará tu voz y el idioma original.\n'
(root/'GUIONES-PARA-GRABAR.md').write_text(md)
(root/'brief-y-beats-provisionales.json').write_text(json.dumps(brief,ensure_ascii=False,indent=2))
